// Turns a declarations object into a CSS declaration string
function styleString(decls) {
  return Object.entries(decls)
    .map(([prop, value]) => `${prop}: ${value};`)
    .join(" ");
}
console.log(styleString({ color: "red", "font-size": "16px" }));

