// Builds a complete CSS rule string from a selector and declarations
function fullRule(selector, decls) {
  const body = Object.entries(decls)
    .map(([prop, value]) => `${prop}: ${value};`)
    .join(" ");
  return `${selector} { ${body} }`;
}
console.log(fullRule(".card", { color: "blue", padding: "8px" }));

